// src/views/Perfil.jsx — con datos reales del usuario autenticado
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { User, Mail, Phone, Edit, Lock, Shield, LogOut } from "lucide-react";
import toast from "react-hot-toast";
import { LogoSeal } from "../components/Layout";
import api from "../utils/api";

export default function Perfil({ usuario, onLogout }) {
  const navigate = useNavigate();

  // Usa los datos reales del usuario autenticado
  const [datos, setDatos] = useState({
    nombre:  usuario?.nombre  || "",
    usuario: usuario?.usuario || "",
    email:   usuario?.email   || "",
    tel:     usuario?.tel     || "",
  });
  const [pass,     setPass]     = useState({ actual:"", nueva:"", confirmar:"" });
  const [editando, setEditando] = useState(null);
  const [guardando,setGuardando]= useState(false);

  const setD = k => e => setDatos(p => ({ ...p, [k]: e.target.value }));
  const setP = k => e => setPass(p  => ({ ...p, [k]: e.target.value }));

  // Fortaleza de contraseña
  const fortaleza = pass.nueva.length === 0 ? null
    : pass.nueva.length < 6  ? { label:"Contraseña débil",  color:"#e74c3c", w:"30%" }
    : pass.nueva.length < 10 ? { label:"Contraseña media",  color:"#f59e0b", w:"60%" }
    :                           { label:"Contraseña fuerte", color:"#2ecc71", w:"100%" };

  const guardarDatos = async () => {
    if (!datos.nombre || !datos.email) {
      toast.error("Nombre y correo son requeridos.");
      return;
    }
    setGuardando(true);
    try {
      // Actualiza los datos en el backend
      await api.put(`/usuarios/${usuario?.id || 1}`, {
        nombre: datos.nombre,
        email:  datos.email,
      });
      toast.success("Datos actualizados correctamente.");
      setEditando(null);
    } catch {
      toast.error("No se pudieron actualizar los datos.");
    } finally {
      setGuardando(false);
    }
  };

  const cambiarPassword = async () => {
    if (!pass.actual) {
      toast.error("Ingrese su contraseña actual.");
      return;
    }
    if (!pass.nueva || pass.nueva.length < 6) {
      toast.error("La nueva contraseña debe tener al menos 6 caracteres.");
      return;
    }
    if (pass.nueva !== pass.confirmar) {
      toast.error("Las contraseñas no coinciden.");
      return;
    }
    setGuardando(true);
    try {
      await api.put(`/usuarios/${usuario?.id || 1}`, {
        password: pass.nueva,
      });
      toast.success("Contraseña actualizada correctamente.");
      setPass({ actual:"", nueva:"", confirmar:"" });
    } catch {
      toast.error("No se pudo actualizar la contraseña.");
    } finally {
      setGuardando(false);
    }
  };

  const cerrarSesion = () => {
    if (onLogout) onLogout();
    navigate("/");
  };

  // Color del badge de rol
  const rolColor = usuario?.rol === "administrador" ? "#6a9fd8" : "#2ecc71";
  const rolBg    = usuario?.rol === "administrador"
    ? "rgba(36,86,164,0.30)"
    : "rgba(26,154,82,0.25)";

  const CAMPOS = [
    { label:"Nombre completo", key:"nombre",  icon:User  },
    { label:"Usuario",         key:"usuario", icon:User  },
    { label:"Correo electrónico", key:"email", icon:Mail },
    { label:"Teléfono",        key:"tel",     icon:Phone },
  ];

  return (
    <div style={{ display:"flex", minHeight:"calc(100vh - 58px)" }} className="fade-up">

      {/* ── Izquierda — datos del perfil ─────────────────── */}
      <div style={{ flex:1, padding:"36px 48px", display:"flex", flexDirection:"column", gap:26, overflowY:"auto" }}>

        <h1 style={{ fontFamily:"'Playfair Display',serif", fontSize:36, fontWeight:800, letterSpacing:"-0.02em" }}>
          Mi Perfil.
        </h1>

        {/* Avatar + info del usuario */}
        <div style={{ display:"flex", alignItems:"center", gap:18 }}>
          <div style={{
            width:68, height:68, borderRadius:"50%", flexShrink:0,
            background: usuario?.rol === "administrador"
              ? "linear-gradient(135deg,#1d4080,#2456a4)"
              : "linear-gradient(135deg,#1a5c36,#2ecc71)",
            border:"2px solid rgba(255,255,255,0.35)",
            display:"flex", alignItems:"center", justifyContent:"center",
            fontWeight:900, fontSize:22, color:"#fff"
          }}>
            {usuario?.initials || "?"}
          </div>
          <div>
            <p style={{ fontFamily:"'Playfair Display',serif", fontSize:20, fontWeight:800 }}>
              {usuario?.nombre || "Usuario"}
            </p>
            <span style={{ background:rolBg, border:`1px solid ${rolColor}`, borderRadius:6, padding:"3px 12px", fontSize:12, fontWeight:600, color:rolColor, display:"inline-block", marginTop:4 }}>
              {usuario?.rol || "operador"}
            </span>
            <p style={{ fontSize:12, color:"rgba(255,255,255,0.40)", marginTop:5 }}>
              {usuario?.email || ""} · Guatemala
            </p>
          </div>
        </div>

        {/* Información personal */}
        <div className="navy-card" style={{ padding:"22px" }}>
          <p style={{ fontWeight:700, fontSize:14, marginBottom:18 }}>Información Personal</p>
          <div style={{ display:"flex", flexDirection:"column", gap:14 }}>
            {CAMPOS.map(({ label, key, icon:Icon }) => (
              <div key={key}>
                <label style={{ display:"block", fontSize:11, color:"rgba(255,255,255,0.40)", marginBottom:6 }}>
                  {label}
                </label>
                <div style={{ position:"relative" }}>
                  <Icon size={14} color="rgba(255,255,255,0.30)"
                    style={{ position:"absolute", left:13, top:"50%", transform:"translateY(-50%)", pointerEvents:"none" }}/>
                  <input
                    className="input-navy"
                    value={datos[key] || ""}
                    onChange={setD(key)}
                    readOnly={editando !== key || key === "usuario"}
                    onClick={() => key !== "usuario" && setEditando(key)}
                    style={{
                      paddingLeft:38, paddingRight:40,
                      cursor: key === "usuario" ? "not-allowed" : editando === key ? "text" : "pointer",
                      opacity: key === "usuario" ? 0.6 : 1,
                      borderColor: editando === key ? "#6a9fd8" : "rgba(255,255,255,0.18)"
                    }}
                    placeholder={key === "tel" ? "+502 0000-0000" : ""}
                  />
                  {key !== "usuario" && (
                    <button
                      onClick={() => setEditando(editando === key ? null : key)}
                      style={{ position:"absolute", right:12, top:"50%", transform:"translateY(-50%)", background:"none", border:"none", cursor:"pointer", color:"rgba(255,255,255,0.35)" }}>
                      <Edit size={13}/>
                    </button>
                  )}
                </div>
                {key === "usuario" && (
                  <p style={{ fontSize:10, color:"rgba(255,255,255,0.25)", marginTop:4 }}>
                    El nombre de usuario no se puede cambiar.
                  </p>
                )}
              </div>
            ))}
            <button
              className="btn-navy"
              style={{ padding:"11px", fontSize:14, borderRadius:9, opacity: guardando ? 0.7 : 1 }}
              onClick={guardarDatos}
              disabled={guardando}>
              {guardando ? "Guardando..." : "Guardar Cambios"}
            </button>
          </div>
        </div>

        {/* Seguridad — cambiar contraseña */}
        <div className="navy-card" style={{ padding:"22px" }}>
          <p style={{ fontWeight:700, fontSize:14, marginBottom:18, display:"flex", alignItems:"center", gap:8 }}>
            <Shield size={16} color="#6a9fd8"/> Seguridad
          </p>
          <div style={{ display:"flex", gap:10, marginBottom:14, flexWrap:"wrap" }}>
            {[
              { label:"Contraseña actual",   key:"actual"    },
              { label:"Nueva contraseña",    key:"nueva"     },
              { label:"Confirmar contraseña",key:"confirmar" },
            ].map(({ label, key }) => (
              <div key={key} style={{ flex:1, minWidth:140 }}>
                <label style={{ display:"block", fontSize:11, color:"rgba(255,255,255,0.40)", marginBottom:6 }}>
                  {label}
                </label>
                <div style={{ position:"relative" }}>
                  <Lock size={13} color="rgba(255,255,255,0.30)"
                    style={{ position:"absolute", left:12, top:"50%", transform:"translateY(-50%)", pointerEvents:"none" }}/>
                  <input
                    className="input-navy"
                    type="password"
                    value={pass[key]}
                    onChange={setP(key)}
                    style={{ paddingLeft:34, fontSize:13 }}
                    placeholder="••••••••"
                  />
                </div>
              </div>
            ))}
          </div>
          {fortaleza && (
            <div style={{ marginBottom:14 }}>
              <div style={{ background:"rgba(255,255,255,0.08)", borderRadius:999, height:3, overflow:"hidden", marginBottom:5 }}>
                <div style={{ background:fortaleza.color, height:"100%", width:fortaleza.w, transition:"all 0.3s" }}/>
              </div>
              <p style={{ fontSize:11, color:fortaleza.color }}>{fortaleza.label}</p>
            </div>
          )}
          <button
            className="btn-navy"
            style={{ padding:"11px 22px", fontSize:14, borderRadius:9, opacity: guardando ? 0.7 : 1 }}
            onClick={cambiarPassword}
            disabled={guardando}>
            {guardando ? "Guardando..." : "Actualizar Contraseña"}
          </button>
        </div>

        {/* Cerrar sesión */}
        <div style={{ borderTop:"1px solid rgba(255,255,255,0.08)", paddingTop:20 }}>
          <p style={{ fontSize:14, fontWeight:700, color:"#e74c3c", display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
            <LogOut size={15}/> Cerrar Sesión
          </p>
          <p style={{ fontSize:12, color:"rgba(255,255,255,0.35)", marginBottom:14 }}>
            Salir del sistema en todos los dispositivos
          </p>
          <button className="btn-danger-outline" onClick={cerrarSesion}>
            Cerrar Sesión
          </button>
        </div>
      </div>

      {/* ── Derecha — logo + foto ─────────────────────────── */}
      <div style={{ width:"38%", position:"relative", overflow:"hidden", flexShrink:0 }}>
        <div className="bg-farm-photo" style={{ position:"absolute", inset:0 }}/>
        <div style={{ position:"absolute", inset:0, background:"linear-gradient(to right,#0a1628 0%,rgba(10,22,40,0.10) 100%)" }}/>
        <div style={{ position:"absolute", top:40, right:40, display:"flex", flexDirection:"column", alignItems:"center", gap:10 }}>
          <LogoSeal size="lg"/>
          <p style={{ fontFamily:"'Playfair Display',serif", fontSize:18, fontWeight:800, color:"#fff", textShadow:"0 2px 12px rgba(0,0,0,0.8)", marginTop:8 }}>
            Lácteos de Oriente
          </p>
          <p style={{ fontSize:12, color:"rgba(255,255,255,0.70)", letterSpacing:"0.06em", textShadow:"0 2px 8px rgba(0,0,0,0.8)" }}>
            Lo fresco mejor
          </p>
        </div>
      </div>

    </div>
  );
}
